[DataContract]public enum ContactRuleMode{[EnumMember] TransientContactAndTime,[EnumMember] ContactLimitAndTime,[EnumMember] TimeOnlyWithJustification,[EnumMember] ITFirstContinuity}
[DataContract]public enum RuleCircuitClass{[EnumMember] Unknown,[EnumMember] Final,[EnumMember] Distribution}
