[DataContract]public sealed class ContactTimeRule {
[DataMember,DisplayName("Critério de contato e desligamento")]public ContactRuleMode Mode{get;set;}[DataMember,DisplayName("Esquema ao qual a regra se aplica")]public EarthingScheme Scheme{get;set;}[DataMember,DisplayName("Classe do circuito na regra")]public RuleCircuitClass CircuitClass{get;set;}[DataMember,DisplayName("U0 mínima da regra (V)")]public double? MinimumU0V{get;set;}[DataMember,DisplayName("U0 máxima da regra (V)")]public double? MaximumU0V{get;set;}[DataMember,DisplayName("Regra limita corrente nominal")]public bool? UsesRatedCurrentLimit{get;set;}[DataMember,DisplayName("Máxima In aplicável (A)")]public double? MaximumRatedA{get;set;}[DataMember,DisplayName("Limite de contato UL (V)")]public double? TouchLimitV{get;set;}[DataMember,DisplayName("Tempo máximo aplicável (s)")]public double? MaximumDisconnectSeconds{get;set;}[DataMember,DisplayName("Referência do potencial comparado")]public FaultVoltageReference PotentialReference{get;set;}[DataMember,DisplayName("Fonte da regra / evidência")]public string Reference{get;set;}[DataMember,DisplayName("Edição / revisão da regra")]public string Edition{get;set;}[DataMember,DisplayName("Cláusula / página")]public string Clause{get;set;}[DataMember,DisplayName("Condições / hipóteses")]public string Conditions{get;set;}[DataMember,DisplayName("Justificativa de somente tempo")]public string NoPotentialComparisonReason{get;set;}
public ContactTimeRule(){Reference=Edition=Clause=Conditions=NoPotentialComparisonReason="";}public ContactTimeRule Copy(){return (ContactTimeRule)MemberwiseClone();}
public void Validate(){if(!Enum.IsDefined(typeof(ContactRuleMode),Mode)||!Enum.IsDefined(typeof(EarthingScheme),Scheme)||!Enum.IsDefined(typeof(RuleCircuitClass),CircuitClass)||!Enum.IsDefined(typeof(FaultVoltageReference),PotentialReference))throw new InvalidDataException("Tipo/escopo de regra inválidos.");foreach(var x in new[]{MinimumU0V,MaximumU0V,MaximumRatedA,TouchLimitV,MaximumDisconnectSeconds})if(x.HasValue)Project.Range(x.Value,.000000001,1e12,"limite da regra");if(MinimumU0V.HasValue&&MaximumU0V.HasValue&&MaximumU0V<MinimumU0V)throw new InvalidDataException("Faixa de tensão da regra invertida.");if(UsesRatedCurrentLimit==false&&MaximumRatedA.HasValue)throw new InvalidDataException("Limite de In declarado como não aplicável não deve conter valor.");if(Mode==ContactRuleMode.ITFirstContinuity&&MaximumDisconnectSeconds.HasValue)throw new InvalidDataException("Continuidade na primeira falta IT não usa o campo de tempo de corte.");foreach(var s in new[]{Reference,Edition,Clause,Conditions,NoPotentialComparisonReason})ReturnSizing.Text(s,false);}
}
[DataContract]public sealed class ClearingTimeRecord {
[DataMember,DisplayName("Dispositivo de interrupção")]public ClearingDevice Device{get;set;}[DataMember]public string Manufacturer{get;set;}[DataMember,DisplayName("Fonte da regra / evidência")]public string Reference{get;set;}[DataMember]public string DeviceConfiguration{get;set;}[DataMember]public double VoltageV{get;set;}[DataMember]public double FrequencyHz{get;set;}[DataMember]public double MinimumCurrentA{get;set;}[DataMember]public double MaximumCurrentA{get;set;}[DataMember]public double UpperSeconds{get;set;}[DataMember]public bool? CoversTotalClearing{get;set;}[DataMember]public bool? IncludesExternalActuator{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember,DisplayName("Condições / hipóteses")]public string Conditions{get;set;}
public ClearingTimeRecord(){Manufacturer=Reference=DeviceConfiguration=Source=DataVersion=Conditions="";}public ClearingTimeRecord Copy(){return (ClearingTimeRecord)MemberwiseClone();}
public void Validate(){if(!Enum.IsDefined(typeof(ClearingDevice),Device)||Device==ClearingDevice.None)throw new InvalidDataException("Dispositivo da evidência inválido.");foreach(var s in new[]{Manufacturer,Reference,Source,DataVersion,Conditions})ReturnSizing.Text(s,true);if(DeviceConfiguration==null||(DeviceConfiguration!=""&&(DeviceConfiguration.Length!=64||DeviceConfiguration.Any(x=>!Uri.IsHexDigit(x)))))throw new InvalidDataException("Configuração da evidência inválida.");Project.Range(VoltageV,1,1e6,"tensão da evidência");Project.Range(FrequencyHz,1,1000,"frequência da evidência");Project.Range(MinimumCurrentA,1e-12,1e15,"corrente mínima da evidência");Project.Range(MaximumCurrentA,MinimumCurrentA,1e15,"corrente máxima da evidência");Project.Range(UpperSeconds,1e-12,1e12,"tempo total superior");}
}
[DataContract]public sealed class ContactTimeStudy {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,Browsable(false)]public ContactTimeRule Rule{get;set;}[DataMember,DisplayName("Dispositivo de interrupção")]public ClearingDevice Device{get;set;}[DataMember,DisplayName("Origem da evidência de tempo")]public ClearingEvidenceMode EvidenceMode{get;set;}[DataMember,Browsable(false)]public ClearingTimeRecord Evidence{get;set;}[DataMember,DisplayName("Curva anexada cobre tempo TOTAL")]public bool? AttachedCurveCoversTotalClearing{get;set;}[DataMember,DisplayName("Documento da natureza da curva")]public string AttachedCurveDocument{get;set;}[DataMember,DisplayName("IMD sinaliza primeira falta")]public bool? IMDSignalsFirstFault{get;set;}[DataMember,DisplayName("IMD: referência e ensaio")]public string IMDReferenceAndTest{get;set;}[DataMember,DisplayName("Existe plano de localizar/reparar")]public bool? FaultLocationAndRepairPlan{get;set;}[DataMember,DisplayName("Referência do plano de manutenção")]public string MaintenancePlanReference{get;set;}
public ContactTimeStudy(){Engine=ContactTime.EngineId;Rule=new ContactTimeRule();AttachedCurveDocument=IMDReferenceAndTest=MaintenancePlanReference="";}public ContactTimeStudy Copy(){return new ContactTimeStudy{Engine=Engine,Rule=Rule.Copy(),Device=Device,EvidenceMode=EvidenceMode,Evidence=Evidence==null?null:Evidence.Copy(),AttachedCurveCoversTotalClearing=AttachedCurveCoversTotalClearing,AttachedCurveDocument=AttachedCurveDocument,IMDSignalsFirstFault=IMDSignalsFirstFault,IMDReferenceAndTest=IMDReferenceAndTest,FaultLocationAndRepairPlan=FaultLocationAndRepairPlan,MaintenancePlanReference=MaintenancePlanReference};}
public void Validate(){if(Engine!=ContactTime.EngineId||Rule==null||!Enum.IsDefined(typeof(ClearingDevice),Device)||!Enum.IsDefined(typeof(ClearingEvidenceMode),EvidenceMode))throw new InvalidDataException("Estudo/revisão de contato/tempo inválidos.");Rule.Validate();if(Evidence!=null)Evidence.Validate();foreach(var s in new[]{AttachedCurveDocument,IMDReferenceAndTest,MaintenancePlanReference})ReturnSizing.Text(s,false);if(Rule.Mode==ContactRuleMode.ITFirstContinuity&&(Device!=ClearingDevice.None||Evidence!=null||AttachedCurveCoversTotalClearing.HasValue||AttachedCurveDocument!=""))throw new InvalidDataException("Continuidade IT1 utiliza monitoramento, sem evidência oculta de corte.");}
}
public sealed partial class Circuit{[DataMember(Order=114),Browsable(false)]public ContactTimeStudy ContactTimeStudy{get;set;}}
public sealed class ContactTimeResult{public string Status,Detail;public double? FaultCurrentA,OperatingCurrentA,TouchVoltageV,UpperClearingSeconds;}
public static class ContactTime {
public const string EngineId="cs-contato-tempo-v1";public const string Header="Device;Manufacturer;Reference;DeviceConfiguration;VoltageV;FrequencyHz;MinimumCurrentA;MaximumCurrentA;UpperSeconds;CoversTotalClearing;IncludesExternalActuator;Source;DataVersion;Conditions";
static void Check(StringBuilder text,string label,bool? value,ref bool fail,ref bool pending){if(!value.HasValue)pending=true;else if(!value.Value)fail=true;text.AppendLine((value.HasValue?(value.Value?"Atende: ":"Não atende: "):"Pendente: ")+label);}
static bool Same(string a,string b){return String.Equals((a??"").Trim(),(b??"").Trim(),StringComparison.OrdinalIgnoreCase);}
static bool DeviceTrace(Circuit c,ClearingDevice device){string[] values=null;if(device==ClearingDevice.PrimaryBreaker&&c.Protection.BreakerSnapshot!=null){var r=c.Protection.BreakerSnapshot.Rating;values=new[]{r.Manufacturer,r.Reference,r.Source,r.DataVersion,r.Standard,r.Sheet};}else if(device==ClearingDevice.SelectedFuse&&c.SwitchgearSelection!=null&&c.SwitchgearSelection.Rating.IsFuse){var r=c.SwitchgearSelection.Rating;values=new[]{r.Manufacturer,r.Reference,r.Source,r.DataVersion,r.Standard,r.Sheet};}else if(device==ClearingDevice.SelectedResidual&&c.ResidualSelection!=null){var r=c.ResidualSelection.Rating;var list=new List<string>(new[]{r.Manufacturer,r.Reference,r.Source,r.DataVersion,r.Standard,r.Conditions,r.AssemblyDocument});if(r.Kind==ResidualKind.ResidualRelay)list.AddRange(new[]{r.SensorReference,r.ActuatorReference});if(r.AccessoryReference!="")list.Add(r.AccessoryReference);values=list.ToArray();}return values!=null&&values.All(v=>!String.IsNullOrWhiteSpace(v)&&!v.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase));}
public static string Configuration(Circuit c,ClearingDevice device){if(!DeviceTrace(c,device))return "";if(device==ClearingDevice.PrimaryBreaker)return Coordination.ProtectionConfiguration(c);if(device==ClearingDevice.SelectedFuse)return c.SwitchgearSelection!=null&&c.SwitchgearSelection.Rating.IsFuse?ProtectionResponses.Hash(c.SwitchgearSelection):"";if(device==ClearingDevice.SelectedResidual)return c.ResidualSelection==null?"":ProtectionResponses.Hash(new[]{ProtectionResponses.Hash(c.ResidualSelection),Coordination.ProtectionConfiguration(c)});return "";}
static void Identity(Circuit c,ClearingDevice device,out string manufacturer,out string reference){manufacturer=reference="";if(device==ClearingDevice.PrimaryBreaker&&c.Protection.BreakerSnapshot!=null){manufacturer=c.Protection.BreakerSnapshot.Rating.Manufacturer;reference=c.Protection.BreakerSnapshot.Rating.Reference;}else if(device==ClearingDevice.SelectedFuse&&c.SwitchgearSelection!=null&&c.SwitchgearSelection.Rating.IsFuse){manufacturer=c.SwitchgearSelection.Rating.Manufacturer;reference=c.SwitchgearSelection.Rating.Reference;}else if(device==ClearingDevice.SelectedResidual&&c.ResidualSelection!=null){manufacturer=c.ResidualSelection.Rating.Manufacturer;reference=c.ResidualSelection.Rating.Reference;}}
static bool? Ready(Project p,Circuit c,ClearingDevice device,double? faultA,StringBuilder text){if(!faultA.HasValue||!DeviceTrace(c,device))return null;var board=p.Boards.First(b=>b.Circuits.Contains(c));var row=new CircuitResult{Circuit=c,Board=board};if(device==ClearingDevice.PrimaryBreaker){if(c.Protection.BreakerSnapshot==null)return null;string detail;bool valid=BreakerSelection.Applicable(p,row,c.Protection.BreakerSnapshot,out detail);text.AppendLine(detail);return valid&&faultA.HasValue&&c.Protection.BreakingCapacityKA>=faultA.Value/1000;}
if(device==ClearingDevice.SelectedFuse){var binding=c.SwitchgearSelection;if(binding==null||!binding.Rating.IsFuse)return null;var r=binding.Rating;return r.VoltageV==c.Voltage&&r.FrequencyHz==p.Frequency&&r.Poles==binding.RequiredPoles&&BreakerSelection.ValidTopology(row,r.Poles)&&faultA.HasValue&&r.BreakingKA>=faultA.Value/1000;}
if(device!=ClearingDevice.SelectedResidual||c.ResidualSelection==null)return null;var rcdBinding=c.ResidualSelection;var residual=rcdBinding.Rating;bool? topology=null;if(c.Conductors!=null){if(c.Phases==PhaseMode.Trifasico)topology=c.Conductors.HasNeutral==true?(bool?)(residual.Poles==PoleLayout.FourPole||residual.Poles==PoleLayout.ThreePoleNeutral):c.Conductors.HasNeutral==false?(bool?)(residual.Poles==PoleLayout.ThreePole||residual.Poles==PoleLayout.FourPole||residual.Poles==PoleLayout.ThreePoleNeutral):null;else topology=c.Conductors.Connection==LiveConnection.LineNeutral?(bool?)(residual.Poles==PoleLayout.OnePoleNeutral||residual.Poles==PoleLayout.TwoPole):c.Conductors.Connection==LiveConnection.LineLine?(bool?)(residual.Poles==PoleLayout.TwoPole):null;}if(!topology.HasValue)return null;bool primaryKnown=c.Protection.BreakerSnapshot!=null&&residual.RequiredPrimaryConfiguration!=""&&residual.RequiredPrimaryConfiguration==ResidualSelection.PrimaryConfiguration(c);if(!primaryKnown||residual.ConditionalKA<=0||rcdBinding.RequiredWaveform==ResidualWaveform.Unknown||rcdBinding.MaximumDeltaMilliA==0||String.IsNullOrWhiteSpace(rcdBinding.RequirementSource))return null;bool pass=topology.Value&&residual.Poles==rcdBinding.RequiredPoles&&residual.VoltageV==c.Voltage&&residual.FrequencyHz==p.Frequency&&residual.Waveform==rcdBinding.RequiredWaveform&&residual.DeltaMilliA<=rcdBinding.MaximumDeltaMilliA&&c.BreakerA<=residual.RatedA&&faultA.HasValue&&residual.ConditionalKA>=faultA.Value/1000&&c.Protection.BreakingCapacityKA>=faultA.Value/1000&&Grounding.EffectiveSystem(p,c)!="TN-C";if(residual.Kind==ResidualKind.ResidualRelay){if(String.IsNullOrWhiteSpace(residual.SensorReference)||String.IsNullOrWhiteSpace(residual.ActuatorReference)||String.IsNullOrWhiteSpace(residual.AssemblyDocument)||residual.ControlVoltageV==0||rcdBinding.ControlVoltageV==0)return null;pass&=residual.ControlVoltageV==rcdBinding.ControlVoltageV&&residual.ControlSupply==rcdBinding.ControlSupply;}if(c.DriveMotor!=null)return null;return pass;}
public static ContactTimeResult Evaluate(Project p,Circuit c,ContactTimeStudy study){p.Validate();if(!p.Boards.Any(b=>b.Circuits.Contains(c)))throw new InvalidDataException("Circuito fora do projeto.");study.Validate();var rule=study.Rule;var loop=FaultLoops.Evaluate(p,c,c.LoopFault);var text=new StringBuilder(EngineId+"; regra "+rule.Reference+"; edição "+rule.Edition+"; cláusula "+rule.Clause+"; condições "+rule.Conditions+"; modo "+rule.Mode+".\r\n");bool fail=false,pending=false;Check(text,"Referência/edição/cláusula/condições identificadas",new[]{rule.Reference,rule.Edition,rule.Clause,rule.Conditions}.Any(String.IsNullOrWhiteSpace)?(bool?)null:true,ref fail,ref pending);Check(text,"Esquema e classe de circuito da regra correspondem ao projeto",p.GroundingSource!=null&&rule.Scheme!=EarthingScheme.Unknown&&rule.CircuitClass!=RuleCircuitClass.Unknown?(bool?)(rule.Scheme==p.GroundingSource.Scheme&&rule.CircuitClass==(c.ChildBoardId==""?RuleCircuitClass.Final:RuleCircuitClass.Distribution)):null,ref fail,ref pending);double u0=p.Source.LineVoltage/Math.Sqrt(3);Check(text,"U0="+u0+" V na faixa "+rule.MinimumU0V+"–"+rule.MaximumU0V+" V da regra",rule.MinimumU0V.HasValue&&rule.MaximumU0V.HasValue?(bool?)(u0>=rule.MinimumU0V&&u0<=rule.MaximumU0V):null,ref fail,ref pending);Check(text,"Aplicabilidade do limite de corrente nominal declarada",rule.UsesRatedCurrentLimit.HasValue?(bool?)true:null,ref fail,ref pending);if(rule.UsesRatedCurrentLimit==true)Check(text,"In do circuito="+c.BreakerA+" A ≤limite "+rule.MaximumRatedA+" A",rule.MaximumRatedA.HasValue&&c.BreakerA>0?(bool?)(c.BreakerA<=rule.MaximumRatedA.Value):null,ref fail,ref pending);Check(text,"Laço calculado no modelo declarado",loop.Current.HasValue?(bool?)true:null,ref fail,ref pending);Check(text,"Fonte compatível com corrente simétrica constante durante a avaliação",p.Source.SupportsConstantImpedanceWaveform?(bool?)true:null,ref fail,ref pending);if(!loop.Current.HasValue)text.AppendLine(loop.Detail);double? operating=null,time=null;
if(rule.Mode==ContactRuleMode.TimeOnlyWithJustification){Check(text,"Dispensa da comparação de potencial justificada",String.IsNullOrWhiteSpace(rule.NoPotentialComparisonReason)?(bool?)null:true,ref fail,ref pending);text.AppendLine("Justificativa da regra: "+rule.NoPotentialComparisonReason+"; potencial disponível="+loop.MetalVoltageV+" V / "+loop.MetalReference+".");}else{Check(text,"Limite de contato e referência de potencial definidos",rule.TouchLimitV.HasValue&&rule.PotentialReference!=FaultVoltageReference.Unknown?(bool?)true:null,ref fail,ref pending);Check(text,"Referência calculada de potencial coincide com a regra",loop.MetalVoltage.HasValue&&rule.PotentialReference!=FaultVoltageReference.Unknown?(bool?)(loop.MetalReference==rule.PotentialReference):null,ref fail,ref pending);if(rule.Mode==ContactRuleMode.TransientContactAndTime){if(loop.MetalVoltageV.HasValue&&rule.TouchLimitV.HasValue)text.AppendLine("Potencial transitório="+loop.MetalVoltageV+" V; UL="+rule.TouchLimitV+" V; "+(loop.MetalVoltageV>rule.TouchLimitV?"acima de UL, exigindo corte no tempo aplicável":"abaixo de UL no caso calculado")+". Não aplicar um limite permanente como reprovação automática de transitório quando a regra permite corte rápido.");}else Check(text,"Potencial="+loop.MetalVoltageV+" V ≤UL="+rule.TouchLimitV+" V",loop.MetalVoltageV.HasValue&&rule.TouchLimitV.HasValue?(bool?)(loop.MetalVoltageV<=rule.TouchLimitV):null,ref fail,ref pending);}
if(rule.Mode==ContactRuleMode.ITFirstContinuity){Check(text,"Caso é primeira falta IT",c.LoopFault!=null&&p.GroundingSource!=null?(bool?)(c.LoopFault.Kind==LoopFaultKind.ITFirst&&p.GroundingSource.Scheme==EarthingScheme.IT):null,ref fail,ref pending);Check(text,"IMD sinaliza a primeira falta",study.IMDSignalsFirstFault,ref fail,ref pending);Check(text,"IMD e ensaio documentados",String.IsNullOrWhiteSpace(study.IMDReferenceAndTest)?(bool?)null:true,ref fail,ref pending);Check(text,"Plano de localização e reparo",study.FaultLocationAndRepairPlan,ref fail,ref pending);Check(text,"Referência do plano",String.IsNullOrWhiteSpace(study.MaintenancePlanReference)?(bool?)null:true,ref fail,ref pending);text.AppendLine("Não se atribui tempo de corte nem aprovação operacional ao simples cadastro do IMD; as declarações/ensaios precisam corresponder à instalação.");}
else{Check(text,"Tempo máximo de desligamento da regra informado",rule.MaximumDisconnectSeconds.HasValue?(bool?)true:null,ref fail,ref pending);Check(text,"Dispositivo identificado e condições/interrupção do caso aplicáveis",Ready(p,c,study.Device,loop.CurrentA,text),ref fail,ref pending);if(study.Device==ClearingDevice.SelectedResidual){operating=loop.ResidualAtOrigin.HasValue?(double?)Complex.Abs(loop.ResidualAtOrigin.Value):null;Check(text,"Corrente residual calculada na origem do circuito, não presumida igual à falta",operating.HasValue?(bool?)true:null,ref fail,ref pending);if(c.ResidualSelection!=null){double delta=c.ResidualSelection.Rating.DeltaMilliA/1000;Check(text,"Ires="+operating+" A ≥ IΔn="+delta+" A",operating.HasValue?(bool?)(operating.Value>=delta):null,ref fail,ref pending);if(p.GroundingSource!=null&&p.GroundingSource.Scheme==EarthingScheme.TT&&rule.TouchLimitV.HasValue&&loop.CurrentA.HasValue&&loop.CurrentA>0&&loop.MetalVoltage.HasValue){double transfer=Complex.Abs(loop.MetalVoltage.Value/loop.Current.Value);Check(text,"TT: |ZPE+Ra|×IΔn="+(transfer*delta)+" V ≤UL="+rule.TouchLimitV+" V",transfer*delta<=rule.TouchLimitV.Value,ref fail,ref pending);}}}else{operating=loop.CurrentA;double? rated=study.Device==ClearingDevice.PrimaryBreaker&&c.Protection.BreakerSnapshot!=null?(double?)c.BreakerA:study.Device==ClearingDevice.SelectedFuse&&c.SwitchgearSelection!=null&&c.SwitchgearSelection.Rating.IsFuse?(double?)c.SwitchgearSelection.Rating.RatedA:null;Check(text,"Sobrecorrente nominal: corrente de atuação não inferior a In (sem disparo externo presumido)",operating.HasValue&&rated.HasValue?(bool?)(operating>=rated):null,ref fail,ref pending);}
if(study.EvidenceMode==ClearingEvidenceMode.DeclaredRange){var record=study.Evidence;if(record==null)Check(text,"Evidência de tempo total ausente",null,ref fail,ref pending);else{string manufacturer,reference;Identity(c,study.Device,out manufacturer,out reference);string config=Configuration(c,study.Device);bool exact=config!=""&&record.DeviceConfiguration!=""&&record.Device==study.Device&&Same(record.Manufacturer,manufacturer)&&Same(record.Reference,reference)&&record.DeviceConfiguration==config&&record.VoltageV==c.Voltage&&record.FrequencyHz==p.Frequency;Check(text,"Dispositivo/tensão/frequência/configuração exatos da evidência",exact?(bool?)true:null,ref fail,ref pending);Check(text,"Evidência cobre tempo total até interrupção",record.CoversTotalClearing==true?(bool?)true:null,ref fail,ref pending);if(study.Device==ClearingDevice.SelectedResidual&&c.ResidualSelection!=null&&c.ResidualSelection.Rating.Kind==ResidualKind.ResidualRelay)Check(text,"Inclui sensor/relé/atuador/abertura do conjunto externo",record.IncludesExternalActuator==true?(bool?)true:null,ref fail,ref pending);bool covered=operating.HasValue&&operating>=record.MinimumCurrentA&&operating<=record.MaximumCurrentA;Check(text,"Corrente de atuação="+operating+" A no intervalo "+record.MinimumCurrentA+"–"+record.MaximumCurrentA+" A, sem extrapolar",covered?(bool?)true:null,ref fail,ref pending);bool chain=study.Device!=ClearingDevice.SelectedResidual||c.ResidualSelection==null||c.ResidualSelection.Rating.Kind!=ResidualKind.ResidualRelay||record.IncludesExternalActuator==true;if(covered&&exact&&record.CoversTotalClearing==true&&chain)time=record.UpperSeconds;text.AppendLine("Limite superior total="+record.UpperSeconds+" s; fonte "+record.Source+"; versão "+record.DataVersion+"; condições "+record.Conditions+".");if(new[]{record.Source,record.DataVersion,record.Conditions}.Any(s=>s.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase)))pending=true;}}
else{Check(text,"Curva t-I não é curva residual neste esquema de importação",study.Device==ClearingDevice.PrimaryBreaker||study.Device==ClearingDevice.SelectedFuse,ref fail,ref pending);Check(text,"Documento confirma envelope de tempo total, não ajuste/retardo",study.AttachedCurveCoversTotalClearing==true?(bool?)true:null,ref fail,ref pending);Check(text,"Documento da natureza do tempo",String.IsNullOrWhiteSpace(study.AttachedCurveDocument)?(bool?)null:true,ref fail,ref pending);var bind=c.ProtectionResponses==null?null:c.ProtectionResponses.Time;string man,reference;Identity(c,study.Device,out man,out reference);bool bound=bind!=null&&ProtectionResponses.Matches(p,c,bind)&&Same(man,bind.Curve.Manufacturer)&&Same(reference,bind.Curve.Reference);Check(text,"Curva t-I vinculada ao dispositivo selecionado",bound?(bool?)true:null,ref fail,ref pending);if(bound&&operating.HasValue&&operating.Value>0){var point=bind.Curve.At(operating.Value);Check(text,"Corrente no domínio da curva sem extrapolação",point!=null?(bool?)true:null,ref fail,ref pending);if(point!=null&&study.AttachedCurveCoversTotalClearing==true&&!String.IsNullOrWhiteSpace(study.AttachedCurveDocument))time=point.Upper;}}
Check(text,"Tempo total superior="+time+" s ≤máximo="+rule.MaximumDisconnectSeconds+" s",time.HasValue&&rule.MaximumDisconnectSeconds.HasValue?(bool?)(time.Value<=rule.MaximumDisconnectSeconds.Value):null,ref fail,ref pending);}
if(p.GroundingSource!=null&&p.GroundingSource.Scheme==EarthingScheme.IT&&rule.Mode!=ContactRuleMode.ITFirstContinuity){Check(text,"IT: sinalização da primeira falta disponível",study.IMDSignalsFirstFault,ref fail,ref pending);Check(text,"IT: ensaio/referência do IMD",String.IsNullOrWhiteSpace(study.IMDReferenceAndTest)?(bool?)null:true,ref fail,ref pending);Check(text,"IT: localização e reparo da falta remanescente",study.FaultLocationAndRepairPlan,ref fail,ref pending);Check(text,"IT: plano de manutenção documentado",String.IsNullOrWhiteSpace(study.MaintenancePlanReference)?(bool?)null:true,ref fail,ref pending);}
if(new[]{rule.Reference,rule.Edition,rule.Clause,rule.Conditions,study.AttachedCurveDocument,study.IMDReferenceAndTest,study.MaintenancePlanReference}.Any(s=>s.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase)))pending=true;text.AppendLine("Ifalta="+loop.CurrentA+" A; Iatuação="+operating+" A; Umassa="+loop.MetalVoltageV+" V / "+loop.MetalReference+". Resultado somente do caso nominal/modelo e da regra declarada. Não certifica norma, condições de mínimos/máximos, autenticidade do documento, medição/continuidade física, seletividade ou toda a instalação. Retardo ajustado isolado nunca substitui tempo total de interrupção.");return new ContactTimeResult{Status=fail?"Não atende ao caso":pending?"Dados incompletos":"Atende comparações do caso declarado",Detail=text.ToString(),FaultCurrentA=loop.CurrentA,OperatingCurrentA=operating,TouchVoltageV=loop.MetalVoltageV,UpperClearingSeconds=time};}
public static void Apply(Project p,Circuit c,ContactTimeStudy study){study.Validate();var result=Evaluate(p,c,study);if(result.Status=="Não atende ao caso")throw new InvalidDataException("Estudo incompatível; nenhuma alteração. "+result.Detail);c.ContactTimeStudy=study.Copy();}
public static ClearingTimeRecord Template(Project p,Circuit c,ClearingDevice device){string man,reference;Identity(c,device,out man,out reference);string config=Configuration(c,device);if(config=="")throw new InvalidDataException("Selecione o dispositivo identificado antes de exportar seu modelo.");return new ClearingTimeRecord{Device=device,Manufacturer=man,Reference=reference,DeviceConfiguration=config,VoltageV=c.Voltage,FrequencyHz=p.Frequency,MinimumCurrentA=.001,MaximumCurrentA=1,UpperSeconds=1,Source="PREENCHER fonte e página",DataVersion="PREENCHER versão",Conditions="PREENCHER tempo total e condições; substituir valores de exemplo"};}
static string Key(ClearingTimeRecord r){return r.Device+"\0"+r.DeviceConfiguration+"\0"+r.Reference+"\0"+r.MinimumCurrentA.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+"\0"+r.MaximumCurrentA.ToString("R",System.Globalization.CultureInfo.InvariantCulture);}
public static List<ClearingTimeRecord> Import(string file){return ComponentCsv.Import<ClearingTimeRecord>(file,Header,r=>r.Validate(),Key);}public static void Export(IEnumerable<ClearingTimeRecord> records,string file){ComponentCsv.Export(records,file,Header,r=>r.Validate(),Key);}
}
